-- Cyprus Lifestyle experiences catalogue — generated by scripts/activities/import-catalog.ts from cyprus-experiences.csv
-- 566 experiences (39 visit northern sites — shown only if ACTIVITIES_NORTH_TOURS=show).
-- Our own titles, summaries, tags, price bands and map areas; each links out to book with the booking partner.
-- Re-runnable: upserts on (provider, external_id); seeded rows no longer in the catalogue are removed (source = 'manual' rows are kept).

on conflict (provider, external_id) do update set slug = excluded.slug, title = excluded.title, summary = excluded.summary, kind = excluded.kind, tags = excluded.tags, district = excluded.district, town = excluded.town, landmark = excluded.landmark, lat = excluded.lat, lng = excluded.lng, geo_precision = excluded.geo_precision, duration_min = excluded.duration_min, duration_label = excluded.duration_label, price_band = excluded.price_band, price_basis = excluded.price_basis, group_max = excluded.group_max, booking_url = excluded.booking_url, visits_north = excluded.visits_north, north_site = excluded.north_site, status = excluded.status, hidden_reason = excluded.hidden_reason, source = excluded.source, curated_at = excluded.curated_at, updated_at = now();

delete from public.activities
